#!/usr/bin/env bash
set -euo pipefail
dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cp -r "$dir/fixtures"/. .

# Commit the baseline dated BEFORE the "Generated by /vibe:sync on 2024-02-01"
# line in .vibe/index.md, so `git log --since=2024-02-01` finds nothing —
# the only change incremental sync should detect is the uncommitted edit to
# src/auth/ below, via `git status --porcelain`.
git init -q -b main
git config user.email "eval@example.com"
git config user.name "Eval Fixture"
git add -A
GIT_AUTHOR_DATE="2024-01-15T09:00:00" GIT_COMMITTER_DATE="2024-01-15T09:00:00" \
  git commit -q -m "chore: initial commit"

# Modify src/auth/ AFTER the commit, and leave it uncommitted.
cat >> src/auth/index.js <<'EOF'

function signOut(session) {
  // Placeholder sign-out: invalidate the session.
  return { session, active: false };
}

module.exports.signOut = signOut;
EOF
